html:
{%- if doc.company -%}
    {%- set company = frappe.get_doc("Company", doc.company) -%}
{%- else -%}
    {%- set default_company = frappe.db.get_single_value('Global Defaults', 'default_company') -%}
    {%- set company = frappe.get_doc("Company", default_company) if default_company else None -%}
{%- endif -%}

{# ---------------- ITEM GROUP MERGING ---------------- #}
{%- set merged_groups = {} -%}
{%- for item in doc.items -%}
    {%- set item_info = frappe.get_cached_value("Item", item.item_code, ["custom_item_type", "stock_uom"], as_dict=1) or {} -%}
    {%- set group_key = item_info.custom_item_type or "Uncategorized" -%}
    {%- set qty = item.ordered_qty | float if item.ordered_qty else 0 -%}

    {%- if group_key in merged_groups -%}
        {%- set _ = merged_groups[group_key].update({
            'qty': merged_groups[group_key].qty + qty
        }) -%}
    {%- else -%}
        {%- set _ = merged_groups.update({
            group_key: {
                'type_name': group_key,
                'uom': item_info.stock_uom or "Nos",
                'qty': qty
            }
        }) -%}
    {%- endif -%}
{%- endfor -%}
{%- set final_groups_list = merged_groups.values() | list -%}

{# ---------------- JOBBER DETAILS ---------------- #}
{%- set jobber_id = doc.panel_jobber if doc.work_type == "Panel Job Work" else doc.full_piece_jobber -%}
{%- set jobber_name = frappe.db.get_value("Supplier", jobber_id, "supplier_name") or jobber_id -%}
{%- set jobber_address = "" -%}

{%- if jobber_id -%}
    {%- set addr_link = frappe.get_all("Dynamic Link",
        filters={"link_doctype": "Supplier", "link_name": jobber_id, "parenttype": "Address"},
        fields=["parent"], limit=1) -%}
    {%- if addr_link -%}
        {%- set addr = frappe.get_doc("Address", addr_link[0].parent) -%}
        {%- set parts = [] -%}
        {%- if addr.address_line1 %}{% set _ = parts.append(addr.address_line1) %}{% endif -%}
        {%- if addr.address_line2 %}{% set _ = parts.append(addr.address_line2) %}{% endif -%}
        {%- if addr.city %}{% set _ = parts.append(addr.city) %}{% endif -%}
        {%- if addr.pincode %}{% set _ = parts.append(addr.pincode) %}{% endif -%}
        {%- set jobber_address = parts | join(", ") -%}
    {%- endif -%}
{%- endif -%}

{# ---------------- PAGINATION ---------------- #}
{% set chunk_size = 20 %}
{% set total = final_groups_list|length %}
{% set pages = (total // chunk_size) + (1 if total % chunk_size else 0) %}
{% if pages == 0 %}{% set pages = 1 %}{% endif %}

<style>
body {
    font-family: Arial, sans-serif;
    font-size: 9pt;
    color: #000;
}

.wrapper {
    width: 100%;
}

.title {
    text-align: center;
    font-weight: bold;
    font-size: 14pt;
    border: 1px solid #000;
    padding: 6px;
    background: #f2f2f2;
}

table {
    width: 100%;
    border-collapse: collapse;
}

th, td {
    border: 1px solid #000;
    padding: 6px;
}

.header-table td {
    vertical-align: top;
}

.text-center {
    text-align: center;
}

.text-right {
    text-align: right;
}

.footer-box {
    margin-top: 15px;
}

.signature-table td {
    height: 60px;
    text-align: center;
}

.page-break {
    page-break-after: always;
}
</style>

{% for page in range(pages) %}
<div class="wrapper">

    <div class="title">EMBROIDERY OR PRINT WORK ORDER</div>

    <!-- HEADER -->
    <table class="header-table">
        <tr>
            <td width="25%" class="text-center">
                <img src="/files/Dacs inc Logo.jpeg" style="max-height:60px;">
            </td>
            <td width="45%" class="text-center">
                <strong style="font-size:11pt;">
                    {{ company.company_name if company else doc.company }}
                </strong><br>
                Jaya Sai Towers No.40, Sajjan Rao Road, Bangalore - 560004<br>
                GSTIN: {{ company.gstin if company else '' }}
            </td>
            <td width="30%">
                <strong>Order No:</strong> {{ doc.name }}<br>
                <strong>Date:</strong> {{ frappe.utils.formatdate(doc.date, "dd-MMM-yyyy") }}<br>
                <strong>Work Type:</strong> {{ doc.work_type }}
            </td>
        </tr>
    </table>

    <!-- JOBBER -->
    <table style="margin-top:8px;">
        <tr>
            <td>
                <strong>Issued To:</strong><br>
                {{ jobber_name or 'Not Specified' }}<br>
                {{ jobber_address or 'Address Not Found' }}
            </td>
        </tr>
    </table>

    <!-- ITEMS -->
    <table style="margin-top:10px;">
        <thead>
            <tr>
                <th width="10%">Sr</th>
                <th width="70%">Item Type / Category</th>
                <th width="20%">Qty</th>
            </tr>
        </thead>
        <tbody>
            {% set start = page * chunk_size %}
            {% set end = start + chunk_size %}
            {% for group in final_groups_list[start:end] %}
            <tr>
                <td class="text-center">{{ loop.index + start }}</td>
                <td><strong>{{ group.type_name }}</strong></td>
                <td class="text-center">
                    {{ "{:,.2f}".format(group.qty) }} {{ group.uom }}
                </td>
            </tr>
            {% endfor %}
        </tbody>
    </table>

    {% if page + 1 == pages %}

    <!-- FOOTER -->
    <div class="footer-box">

        <table>
            <tr>
                <td width="80%" class="text-right">
                    <strong>Grand Total Quantity:</strong>
                </td>
                <td width="20%" class="text-center">
                    {% set total_qty = namespace(val=0) %}
                    {% for g in final_groups_list %}
                        {% set total_qty.val = total_qty.val + g.qty %}
                    {% endfor %}
                    <strong>{{ "{:,.2f}".format(total_qty.val) }}</strong>
                </td>
            </tr>
        </table>

        <table class="signature-table" style="margin-top:20px;">
            <tr>
                <td width="33%">
                    ______________________<br>
                    Receiver's Signature
                </td>
                <td width="33%">
                    ______________________<br>
                    Verified By
                </td>
                <td width="33%">
                    For {{ company.company_name if company else '' }}<br>
                    ______________________<br>
                    Authorised Signatory
                </td>
            </tr>
        </table>

    </div>

    {% endif %}

</div>

{% if not loop.last %}
<div class="page-break"></div>
{% endif %}

{% endfor %}
